    IndexMappings currentMappings = getIndexMappings(tableName);

    // Use a set to store the field names of the current index
    Set<String> currentFieldNames = new HashSet<>();
    for (FieldMapping fieldMapping : currentMappings.getFields()) {
        currentFieldNames.add(fieldMapping.getName());
    }

    // Iterate over the history mappings, and add any new fields to the diff mappings
    Mappings diffMappings = new Mappings();
    for (FieldMapping fieldMapping : mappings.getFields()) {
        if (!currentFieldNames.contains(fieldMapping.getName())) {
            diffMappings.addFieldMapping(fieldMapping);
        }
    }

    // Return the diff mappings
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the existing mappings for the table
    Mappings existingMappings = getExistingMappings(tableName);

    // Create a new mappings instance with the same name as the table
    Mappings newMappings = new Mappings(tableName);

    // Iterate over the fields in the input mappings
    for (FieldMapping fieldMapping : mappings.getFieldMappings()) {
        // If the field does not exist in the existing mappings, add it to the new mappings
        if (!existingMappings.hasField(fieldMapping.getName())) {
            newMappings.addFieldMapping(fieldMapping);
        }
    }

    // Remove the _source config from the new mappings to avoid current index update conflict
    newMappings.setSource(null);

    return newMappings;
}

